code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
    # Horizontal edge bars provide inward rays at their two endpoints.
    bars = []
    for r in range(h):
        c = 0
        while c < w:
            v = g[r][c]
            end = c + 1
            while end < w and g[r][end] == v:
                end += 1
            if v != bg and end - c >= 2 and (r == 0 or r == h - 1):
                bars.append((r, c, end - 1))
            c = end
    # Use the color of the isolated targets aligned with ray columns.
    targets = {}
    for r, c0, c1 in bars:
        for col in {c0, c1}:
            step = 1 if r == 0 else -1
            rr = r + step
            while 0 <= rr < h:
                v = g[rr][col]
                if v != bg and all(v != g[rr][cc] for cc in (col-1, col+1) if 0 <= cc < w):
                    targets.setdefault(col, v)
                    break
                rr += step
    colors = list(targets.values())
    ray_color = colors[0] if colors else None
    for r, c0, c1 in bars:
        step = 1 if r == 0 else -1
        for col in {c0, c1}:
            rr = r + step
            while 0 <= rr < h:
                if g[rr][col] != bg:
                    # An aligned target is converted to 4; preserve unrelated objects.
                    if col in targets and g[rr][col] == targets[col]:
                        g[rr][col] = 4
                    break
                if ray_color is not None:
                    g[rr][col] = ray_color
                rr += step
    return g
'''
